class UserMapper:                                # one owner of the translation
    def to_domain(self, dto: UserDto) -> User:
        return User(id=dto.id, name=dto.full_name, admin=dto.is_admin or False)
    def to_dto(self, user: User) -> UserDto:
        return UserDto(id=user.id, full_name=user.name, is_admin=user.admin)

